class MorePage extends StatelessWidget { const MorePage({super.key});
  @override Widget build(BuildContext context) { final items = [
    ('Dividenden', Icons.payments_outlined, const DividendsPage()), ('ETF-Rechner', Icons.calculate_outlined, const CalculatorPage()), ('Fahrzeuge', Icons.directions_car_outlined, const VehiclesPage()), ('Fahrtkosten', Icons.route_outlined, const TripCalculatorPage()), ('Import & Export', Icons.import_export, const TransferPage()), ('Einstellungen', Icons.settings_outlined, const SettingsPage()),
  ]; return Padding(padding: const EdgeInsets.all(24), child: Column(children: [const PageHeading('Mehr', subtitle: 'Rechner, Mobilität, Datenaustausch und Einstellungen.'), const SizedBox(height: 20), Expanded(child: GridView.builder(gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent: 340, mainAxisExtent: 130, crossAxisSpacing: 14, mainAxisSpacing: 14), itemCount: items.length, itemBuilder: (_, i) => Card(child: InkWell(borderRadius: BorderRadius.circular(24), onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => items[i].$3)), child: Padding(padding: const EdgeInsets.all(20), child: Row(children: [Icon(items[i].$2, size: 32, color: Theme.of(context).colorScheme.primary), const SizedBox(width: 16), Expanded(child: Text(items[i].$1, style: Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w700))), const Icon(Icons.chevron_right)])))))])); }
